import type { ModelInfo, Person, ProviderInfo } from '../../lib/api';
import type { PtyCreateOptions } from '../../types/electron';
import { personInitialPrompt } from './personRunner';

/**
 * Provider conversation-resume dialects (Slice 4), verified against the
 * installed CLIs' own --help output:
 *
 * - claude: accepts an assigned `--session-id <uuid>` at launch and
 *   `--resume <id>` later. Assign strategy.
 * - copilot: `--session-id <id>` sets or resumes a session UUID. Assign.
 * - codex: `codex resume <id>`, but the id is generated by Codex itself
 *   and recorded in its rollout files. Capture strategy (the PTY host
 *   captures it; see electron/provider-session-capture.ts).
 * - opencode: session ids are timestamp-encoded (`ses_...`) and cannot
 *   be assigned safely; capture would need its server/DB. Unsupported.
 * - gemini and unknown runners: unsupported until verified locally.
 *
 * Unsupported never guesses flags: the session simply is not resumable
 * and the UI says so.
 */
export type ProviderResumeSupport = { kind: 'assign' } | { kind: 'capture' } | null;

export function providerResumeSupport(providerId: string): ProviderResumeSupport {
  switch (providerId) {
    case 'claude':
    case 'copilot':
      return { kind: 'assign' };
    case 'codex':
      return { kind: 'capture' };
    default:
      return null;
  }
}

export function canResumeConversation(providerId: string, providerSessionId: string | undefined): boolean {
  return Boolean(providerSessionId) && providerResumeSupport(providerId) !== null;
}

/** UUID for assign-strategy runners (claude/copilot `--session-id`). */
export function newProviderSessionId(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
  // Fallback for non-secure contexts: RFC 4122 v4 shape from getRandomValues.
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  bytes[6] = (bytes[6]! & 0x0f) | 0x40;
  bytes[8] = (bytes[8]! & 0x3f) | 0x80;
  const hex = [...bytes].map((byte) => byte.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

/**
 * Build an argv-only PTY launch that resumes a previous provider
 * conversation in a brand-new PTY (and a new Toolkit session record).
 * Returns null when the runner cannot resume or is unavailable.
 */
export function personResumeOptions(
  person: Person,
  provider: ProviderInfo,
  model: ModelInfo | undefined,
  cwd: string,
  projectId: string,
  providerSessionId: string,
  task = '',
): PtyCreateOptions | null {
  if (!provider.available || provider.id === 'skeleton' || !provider.bin || !cwd) return null;
  if (!canResumeConversation(provider.id, providerSessionId)) return null;
  const prompt = personInitialPrompt(person, task);
  const args: string[] = [];
  switch (provider.id) {
    case 'claude':
      if (model?.model) args.push('--model', model.model);
      args.push('--resume', providerSessionId);
      if (prompt) args.push(prompt);
      break;
    case 'codex':
      // `codex resume` has no --model flag; the conversation keeps its model.
      args.push('resume', providerSessionId);
      if (prompt) args.push(prompt);
      break;
    case 'copilot':
      if (model?.model) args.push('--model', model.model);
      args.push('--session-id', providerSessionId);
      if (prompt) args.push('--interactive', prompt);
      break;
    default:
      return null;
  }
  return {
    agent: person.name,
    personId: person.id,
    projectId,
    provider: provider.id,
    model: model?.model,
    providerSessionId,
    cmd: provider.bin,
    args,
    cwd,
    ...(person.budget?.max_seconds ? { maxSeconds: person.budget.max_seconds } : {}),
  };
}
